# 45_ministerial_departures_break_test.R
# Formal Chow break test on the ministerial departure-rate series (Figure
# 3.5), to answer PJ's question, 8 Sep: "also addition work needed on 2009
# scandal as turning point?" - i.e. is there a genuine, statistically
# identifiable single-year break near 2009 (Parliamentary Standards Act,
# R v Chaytor), or is the rise smoother/later than that?
#
# METHOD: same mean-shift Chow (df1=1) + permutation significance test
# already used for the professionalisation composite's break analysis
# (composite_canonical/build_canonical_composite.R's chow_F_meanshift /
# supF_meanshift / NPERM=10000) - reused verbatim for a like-for-like result,
# not a new ad hoc method.
#
# DATA: data/processed/ministerial_departures_annual_1979_2025.csv
# OUTPUT: console only - diagnostic, not yet a figure or appendix table.

if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
d <- read_csv(file.path(PROJECT, "data/processed/ministerial_departures_annual_1979_2025.csv"),
              show_col_types = FALSE) |> arrange(year)

# ⚠ ADDED 11 Sep 2026 — PJ's chapter text cites "the breakpoints are
# respectively 2015 or 2016" for the two lines on Figure 3.5, but that claim
# was computed against TOTAL (this script's original scope). Fig 3.5's top
# series was relabelled from "Total" to "Reshuffles" earlier this session
# (reshuffle_rate_pct = total_rate_pct - standalone_rate_pct) and was never
# separately break-tested since. Added here as a third series, same method,
# so the chapter's break-year claim can be checked against what the figure
# actually plots.
d$reshuffle_rate_pct <- d$total_rate_pct - d$standalone_rate_pct

set.seed(42)
NPERM <- 10000

.rss_mean <- function(y) { s <- sum((y - mean(y))^2); if (is.na(s)) 0 else s }
chow_F_meanshift <- function(y, k, min_seg = 3) {
  n <- length(y); if (k < min_seg || k > n - min_seg) return(NA_real_)
  rss_pool <- .rss_mean(y); rss_split <- .rss_mean(y[1:k]) + .rss_mean(y[(k + 1):n])
  if (rss_split <= 0) return(NA_real_)
  ((rss_pool - rss_split) / 1) / (rss_split / (n - 2))
}
.ks_interior <- function(n, trim = 0.15, min_seg = 3) {
  lo <- max(min_seg, floor(trim * n)); hi <- min(n - min_seg, n - floor(trim * n)); lo:hi
}
supF_meanshift <- function(y, year, trim = 0.15, min_seg = 3) {
  n <- length(y); ks <- .ks_interior(n, trim, min_seg)
  f <- vapply(ks, function(k) chow_F_meanshift(y, k, min_seg), numeric(1))
  list(peak_year = year[ks[which.max(f)]], peak_F = max(f, na.rm = TRUE),
       curve = data.frame(year = year[ks], F = f))
}
perm_pvalue <- function(y, year, observed_F, trim = 0.15, min_seg = 3, nperm = NPERM) {
  perm_max <- replicate(nperm, {
    ys <- sample(y)
    supF_meanshift(ys, year, trim, min_seg)$peak_F
  })
  mean(perm_max >= observed_F, na.rm = TRUE)
}

for (series in c("total_rate_pct", "standalone_rate_pct", "reshuffle_rate_pct")) {
  y <- d[[series]]; yr <- d$year
  res <- supF_meanshift(y, yr)
  pval <- perm_pvalue(y, yr, res$peak_F)
  cat(sprintf("\n=== %s ===\n", series))
  cat(sprintf("Peak break year: %d, F = %.2f, permutation p = %.4f (%d draws)\n",
              res$peak_year, res$peak_F, pval, NPERM))
  cat("Top 5 candidate years by F:\n")
  print(res$curve |> arrange(desc(F)) |> head(5))
}
